'use strict';
var step = 0;
export function update(value) {
  if (step === 30) {
    var before = thisLayer.getLocalBoneTransform(5);
    var result = thisLayer.applyBonePhysicsImpulse(5, new Vec3(0), new Vec3(12, -8, 15));
    var after = thisLayer.getLocalBoneTransform(5);
    console.log('BoneAngularImpulse', result === undefined, JSON.stringify(before) === JSON.stringify(after));
  }
  if (step === 30 || step === 60) {
    var beforeLimited = thisLayer.getLocalBoneTransform(7);
    var angular = step === 30 ? new Vec3(12, -8, 35) : new Vec3(-9, 7, -40);
    var limitResult = thisLayer.applyBonePhysicsImpulse(7, new Vec3(0), angular);
    var afterLimited = thisLayer.getLocalBoneTransform(7);
    console.log('BoneLimitImpulse', step, limitResult === undefined, JSON.stringify(beforeLimited) === JSON.stringify(afterLimited));
  }
  var poses = [];
  for (var b = 0; b < 17; ++b) {
    poses.push(thisLayer.getLocalBoneTransform(b));
  }
  console.log('BoneMask', thisLayer.name, step++, '[]', JSON.stringify(poses));
  return value;
}

