'use strict';

const DRAG_MAX_DISTANCE = 100;
var activeDragBone = -1;
var dragDelta;
var dragStart;

/**
 * @param {Boolean} value - for property 'visible'
 * @return {Boolean} - update current property value
 */
function authoredUpdate(value) {
	if (activeDragBone >= 0) {
		var drag = input.cursorWorldPosition.subtract(dragStart);
		var dragDist = drag.length();
		drag = drag.divide(dragDist);
		drag = dragStart.add(drag.multiply(Math.min(DRAG_MAX_DISTANCE, dragDist)));
		thisLayer.setBoneTransform(activeDragBone, thisLayer.getBoneTransform(activeDragBone).translation(drag.add(dragDelta)));
	}
}

/**
 * @param {ICursorEvent} event
 */
export function cursorDown(event) {
	var bonePos = thisLayer.getBoneTransform(1).translation();
	var delta = bonePos.copy().subtract(input.cursorWorldPosition);
	var len = delta.length();
	if (len < DRAG_MAX_DISTANCE) {
		dragStart = bonePos;
		dragDelta = delta;
		activeDragBone = 1;
	}
}

/**
 * @param {ICursorEvent} event
 */
export function cursorUp(event) {
	activeDragBone = -1;
}

// Observe the authored drag and release without changing its bone writes.
var probeStep = 0;
export function update(value) {
  if (probeStep === 180) {
    var beforeImpulse = thisLayer.getLocalBoneOrigin(1);
    var firstImpulse = thisLayer.applyBonePhysicsImpulse(1, new Vec3(120, -60, 30), new Vec3(0));
    var betweenImpulses = thisLayer.getLocalBoneOrigin(1);
    var secondImpulse = thisLayer.applyBonePhysicsImpulse(1, new Vec3(-30, 20, -10), new Vec3(0));
    var afterImpulse = thisLayer.getLocalBoneOrigin(1);
    console.log('Q23Impulse returns', firstImpulse === undefined, secondImpulse === undefined);
    console.log('Q23Impulse same-frame', JSON.stringify(beforeImpulse) === JSON.stringify(betweenImpulses), JSON.stringify(beforeImpulse) === JSON.stringify(afterImpulse));
  }
  if (probeStep === 270) {
    thisLayer.applyBonePhysicsImpulse(1, new Vec3(90, -45, 15), new Vec3(0));
  }
  if (probeStep === 273) {
    var beforeReset = thisLayer.getLocalBoneOrigin(1);
    var rootBeforeReset = thisLayer.getLocalBoneOrigin(0);
    console.log('Q24Reset member', 'resetBonePhysicsSimulation' in thisLayer);
    try {
      var firstReset = thisLayer.resetBonePhysicsSimulation(1);
      var betweenResets = thisLayer.getLocalBoneOrigin(1);
      var secondReset = thisLayer.resetBonePhysicsSimulation(1);
      var afterReset = thisLayer.getLocalBoneOrigin(1);
      console.log('Q24Reset returns', firstReset === undefined, secondReset === undefined);
      console.log('Q24Reset same-frame', JSON.stringify(beforeReset) === JSON.stringify(betweenResets), JSON.stringify(beforeReset) === JSON.stringify(afterReset));
      console.log('Q24Reset root', JSON.stringify(rootBeforeReset) === JSON.stringify(thisLayer.getLocalBoneOrigin(0)));
    } catch (error) {
      console.log('Q24Reset error', error.name);
    }
  }
  var result = authoredUpdate(value);
  console.log('Q20Bone', probeStep, activeDragBone, JSON.stringify(thisLayer.getLocalBoneOrigin(1)));
  probeStep += 1;
  return result;
}

