let done = false;
export function init() {
    const result = console.log('Q03 parameters', 7, true, null, undefined, '雪', '😀', '100%', '%s');
    const order = [];
    console.log('Q03 conversion', {toString() { order.push('first'); return 'first'; }}, {toString() { order.push('second'); return 'second'; }}, [1, 2]);
    console.log();
    const failure = new Error('conversion sentinel');
    let caught = false;
    try { console.log('Q03 incomplete', {toString() { throw failure; }}); } catch (e) { caught = e === failure; }
    const state = {returned: result === undefined, order: order.join(','), caught};
    localStorage.set('console-log', state);
    return state.returned && state.order === 'first,second' && caught ? 'Q03 PASS' : 'Q03 FAIL';
}
export function update(value) {
    if (!done) { console.log('Q03 update', 'ready'); done = true; }
    return value;
}

