    if (owners.length) {
        rows.push(inspect('image', thisScene.getLayer('selection-image'), 7));
        rows.push(inspect('text', thisScene.getLayer('selection-text'), 7));
    }
    rows.push(inspect('empty-image', thisScene.getLayer('empty-selection-image'), 0));
    rows.push(inspect('thisObject', thisObject, 0));
    rows.push(inspect('thisLayer', thisLayer, 0));
    const failures = rows.reduce((sum, row) => sum + row.checks.filter(check => !check.ok).length, 0);
    status = 'phase=' + phase + ' live=' + owners.length + ' lifetime=' + lifetime + ' failures=' + failures
        + '
' + rows.map(row => row.label + ':' + row.checks.map(check => check.ok ? '1' : '0').join('')).join('
');
    // Persist compact observations in the capture's isolated localStorage directory.
    // The current console.log host hook does not emit an observation record.
    localStorage.set('layer-effect-selection-' + phase, {dynamic, phase, lifetime, failures,
        rows:rows.map(row => ({label:row.label, selected:row.selected,
            checks:row.checks.map(check => [check.name, check.actual, check.expected, check.ok])}))});
    return status;
}

