'use strict';
const plain = engine.registerAsset('materials/retirement-plain.json');
const scripted = engine.registerAsset('materials/retirement-scripted.json');
const ownerScript = "'use strict';\nexport function destroy() {\n    shared.retirementEvents.push('layer-destroy');\n    console.log('OWNER_RETIRE layer-destroy ' + thisLayer.name);\n    engine.setTimeout(() => { shared.retirementStaleTicks++; }, 0);\n}";
const survivorScript = "'use strict';\nlet ended = false;\nexport function init(value) {\n    shared.retirementSurvivorInits++;\n    engine.setInterval(() => {\n        if (ended) shared.retirementStaleTicks++;\n        shared.retirementSurvivorTicks++;\n    }, 0);\n    return value;\n}\nexport function update(value) {\n    if (ended) shared.retirementStaleTicks++;\n    return value;\n}\nexport function destroy() { ended = true; }";
let model, owner, hidden, survivor, replacement, phase = -1;
function geometry(material) {
    return {
        vertexBuffer: new Float32Array([
            -180,-180,0,0,0, 180,-180,0,1,0, 180,180,0,1,1,
            -180,-180,0,0,0, 180,180,0,1,1, -180,180,0,0,1]),
        vertexFormat: [IModelData.POSITION, IModelData.UV],
        material
    };
}
function createCycle() {
    model = thisScene.createModelData(geometry(plain));
    owner = thisScene.createLayer({
        name:'removed-owner', model,
        origin:{value:'480 540 0', script:ownerScript},
        scale:'1 1 1', angles:'0 0 0', perspective:false
    });
    survivor = thisScene.createLayer({
        name:'surviving-script', image:'models/retirement-card.json',
        origin:{value:'1180 540 0', script:survivorScript},
        scale:'1 1 1', angles:'0 0 0'
    });
    hidden = thisScene.createLayer({
        name:'hidden-shared-model', model, origin:'480 540 0',
        scale:'1 1 1', angles:'0 0 0', visible:false, perspective:false
    });
}
export function init(value) {
    shared.retirementEvents = [];
    shared.retirementStaleTicks = 0;
    shared.retirementSurvivorInits = 0;
    shared.retirementSurvivorTicks = 0;
    shared.retirementMaterialInits = 0;
    shared.retirementMaterialTicks = 0;
    shared.retirementTeardown = false;
    shared.retirementSpawn = () => {
        replacement = thisScene.createLayer({
            name:'callback-replacement', image:'models/retirement-card.json',
            origin:{value:'480 540 0', script:survivorScript},
            scale:'1 1 1', angles:'0 0 0'
        });
        shared.retirementEvents.push('created:' + replacement.name);
        console.log('OWNER_RETIRE replacement-created ' + replacement.name);
    };
    createCycle();
    return value;
}
export function applyUserProperties(properties) {
    if (!model || typeof properties.phase !== 'number' || properties.phase === phase) return;
    phase = properties.phase;
    console.log('OWNER_RETIRE phase ' + phase);
    const operation = phase % 6;
    if (operation === 0 && phase > 0) {
        thisScene.destroyModelData(model);
        createCycle();
    }
    if (operation === 1) model.replaceData({shapes:[geometry(scripted)]});
    if (operation === 2) thisScene.destroyLayer(owner);
    if (operation === 3) hidden.visible = true;
    if (operation === 4) thisScene.destroyLayer(hidden);
    if (operation === 5) {
        thisScene.destroyLayer(survivor);
        thisScene.destroyLayer(replacement);
    }
}
export function update() {
    return 'phase=' + phase + ' callbacks=' + shared.retirementEvents.length
        + ' inits=' + shared.retirementSurvivorInits + '/' + shared.retirementMaterialInits
        + ' stale=' + shared.retirementStaleTicks;
}
export function destroy() {
    shared.retirementTeardown = true;
    thisScene.destroyModelData(model);
}

