let previous = -1;
export function update(value) {
  const phase = Math.min(8, Math.floor((engine.runtime + 0.00001) * 3));
  const row = cases[phase];
  const reference = thisScene.getLayer('attachment-reference');
  reference.origin = new Vec3(...row.origin);
  reference.angles = new Vec3(0, 0, row.angle);
  reference.scale = new Vec3(row.scale, row.scale, 1);
  thisLayer.size = new Vec2(...row.size);
  try {
    const matrix = thisLayer.transformAttachmentToTexture(751, 0);
    const origin = matrix.translation();
    const point = matrix.transformPoint(new Vec2(0.25, 0.5));
    const markerOrigin = new Vec3(960 + (origin.x - 0.5) * row.size[0],
                                  540 - (origin.y - 0.5) * row.size[1], 0);
    const markerPoint = new Vec3(960 + (point.x - 0.5) * row.size[0],
                                 540 - (point.y - 0.5) * row.size[1], 0);
    thisScene.getLayer('attachment-origin').origin = markerOrigin;
    thisScene.getLayer('attachment-point').origin = markerPoint;
    if (phase !== previous) {
      const valid = matrix instanceof Mat3 && matrix.m.length === 9 &&
        matrix.m.every((x, i) => Number.isFinite(x) && Math.abs(x - row.expected[i]) < 0.000001);
      console.log('AttachmentTexture verified', phase, valid);
      console.log('AttachmentTexture', JSON.stringify({phase,
        isMat3: matrix instanceof Mat3, m: matrix.m, origin, point,
        markerOrigin, markerPoint,
        attachment: reference.getAttachmentMatrix(0).m}));
    }
  } catch (error) {
    if (phase !== previous) console.log('AttachmentTexture missing', phase, String(error));
  }
  previous = phase;
  return value;
}

